<?php
namespace App\Domain\Cosmetics\Services; use App\Domain\Cosmetics\Models\{CosmeticDefinition,UserLoadout}; use App\Domain\Rewards\Models\UserEntitlement; use App\Models\User; use App\Support\ApiException;
class CosmeticService { public function listDefinitions(){return CosmeticDefinition::where('enabled',true)->orderBy('category')->orderBy('key')->get();} public function equip(User $u,string $category,string $key):UserLoadout{$c=CosmeticDefinition::where(['key'=>$key,'category'=>$category,'enabled'=>true])->firstOr(fn()=>throw ApiException::notFound('Cosmetic not found.'));$owned=$c->default_owned||UserEntitlement::where(['user_id'=>$u->id,'entitlement_type'=>'cosmetic','entitlement_key'=>$key])->whereNull('revoked_at')->exists();if(!$owned)throw ApiException::forbidden('Cosmetic is not owned.');return UserLoadout::updateOrCreate(['user_id'=>$u->id,'category'=>$category],['cosmetic_key'=>$key]);} public function unequip(User $u,string $category):?UserLoadout{$default=CosmeticDefinition::where(['category'=>$category,'default_owned'=>true,'enabled'=>true])->orderBy('id')->first();if(!$default){UserLoadout::where(['user_id'=>$u->id,'category'=>$category])->delete();return null;}return $this->equip($u,$category,$default->key);} public function getLoadout(User $u){return UserLoadout::where('user_id',$u->id)->get()->keyBy('category');} }
